const onKeydown = event => { if (event.key === 'Escape') closeModal() }
onMounted(() => { animate(stat1.value, 1000, '+'); animate(stat2.value, 95, '%'); animate(stat3.value, 10, '+'); document.addEventListener('keydown', onKeydown) }); onUnmounted(() => { document.removeEventListener('keydown', onKeydown); document.body.classList.remove('modal-open') })
